interface LanguageContextValue {
  language: Language;
  setLanguage: (language: Language) => void;
  t: (text: string, values?: Record<string, string | number>) => string;
}

const LanguageContext = createContext<LanguageContextValue | null>(null);

export function LanguageProvider({ children }: { children: ReactNode }) {
  const [language, setLanguage] = useState<Language>(() => {
    const saved = localStorage.getItem('so-docente-language');
    return saved === 'en' || saved === 'es' || saved === 'zh' ? saved : 'pt';
  });

  useEffect(() => {
    localStorage.setItem('so-docente-language', language);
    document.documentElement.lang = language === 'zh' ? 'zh-CN' : language === 'pt' ? 'pt-BR' : language;
    document.title = language === 'pt'
      ? 'SO Docente Hub | Ensino de Sistemas Operacionais'
      : MESSAGES[language]['SO Docente Hub | Ensino de Sistemas Operacionais'];
    document.querySelector('meta[name="description"]')?.setAttribute(
      'content',
      language === 'pt'
        ? 'Recursos gamificados e questionários para ensinar Sistemas Operacionais.'
        : MESSAGES[language]['Recursos gamificados e questionários para ensinar Sistemas Operacionais.'],
    );
  }, [language]);

  const value = useMemo<LanguageContextValue>(() => ({
    language,
    setLanguage,
    t: (text, values) => {
      const translated = language === 'pt' ? text : MESSAGES[language][text] ?? EXTRA_MESSAGES[language][text] ?? text;
      return Object.entries(values ?? {}).reduce(
        (result, [name, value]) => result.replaceAll(`{${name}}`, String(value)),
        translated,
      );
    },
  }), [language]);

  return <LanguageContext.Provider value={value}>{children}</LanguageContext.Provider>;
}

// eslint-disable-next-line react-refresh/only-export-components
export function useLanguage() {
  const context = useContext(LanguageContext);
  if (!context) throw new Error('useLanguage must be used within a LanguageProvider');
  return context;
}

// eslint-disable-next-line react-refresh/only-export-components
export { LANGUAGE_NAMES };
